#include <cassert>
#include <chrono>
#include <iostream>
bool valid_date(int y, unsigned m, unsigned d) {
    using namespace std::chrono;
    return year_month_day{year{y}, month{m}, day{d}}.ok();
}
int main() {
    assert(valid_date(2024, 2, 29));
    assert(!valid_date(2023, 2, 29));
    std::cout << "date tests passed\n";
}
